// seedProgress inserts one playback_progress row with explicit stamps —
// the adopt tests control updated_at directly instead of riding the
// service clock, so the newer-wins orderings are deterministic.
func seedProgress(t *testing.T, s *Service, userID int64, item string, position int, stamp time.Time) {
	t.Helper()
	_, err := s.st.DB().ExecContext(context.Background(),
		`INSERT INTO playback_progress (user_id, item_id, position_seconds, updated_at) VALUES (?, ?, ?, ?)`,
		userID, item, position, formatStamp(stamp))
	if err != nil {
		t.Fatalf("seed progress %s (user %d): %v", item, userID, err)
	}
}

// seedWatched inserts one watched_items row with explicit stamps (the
// adopt comparator for watched rows is completed_at — the table carries no
// updated_at).
func seedWatched(t *testing.T, s *Service, userID int64, item string, libraryID int64, seriesPath *string, completed, applied *time.Time) {
	t.Helper()
	stamp := func(p *time.Time) any {
		if p == nil {
			return nil
		}
		return formatStamp(*p)
	}
	_, err := s.st.DB().ExecContext(context.Background(),
		`INSERT INTO watched_items (user_id, item_id, library_id, series_relative_path, completed_at, applied_at) VALUES (?, ?, ?, ?, ?, ?)`,
		userID, item, libraryID, seriesPath, stamp(completed), stamp(applied))
	if err != nil {
		t.Fatalf("seed watched %s (user %d): %v", item, userID, err)
	}
}

// progressAt reads one playback_progress row (position + stamp) by slot;
// a missing row reads as zero-position and a zero time.
func progressAt(t *testing.T, s *Service, userID int64, item string) (int, time.Time) {
	t.Helper()
	var (
		pos   int
		stamp string
	)
	err := s.st.DB().QueryRowContext(context.Background(),
		`SELECT position_seconds, updated_at FROM playback_progress WHERE user_id = ? AND item_id = ?`,
		userID, item).Scan(&pos, &stamp)
	if err != nil {
		t.Fatalf("read progress %s (user %d): %v", item, userID, err)
	}
	ts, err := time.Parse(time.RFC3339Nano, stamp)
	if err != nil {
		t.Fatalf("parse progress stamp %q: %v", stamp, err)
	}
	return pos, ts
}

